function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const rows = plain(Inputs.items) || [];
const programme = rows[0];
if (!programme) return;
Outputs.projectName = programme.projectName || '';
Outputs.problemStatement = programme.problemStatement || '';
Outputs.endsOn = programme.endsOn || '';
Outputs.entries = programme.entries || [];
/* The objectives the coach and the learner agreed, with the target each was
   agreed at. An ARCHIVED one is still here: its ratings were really given, and
   dropping them would be the chart omitting points without saying so. */
Outputs.dimensions = programme.dimensions || [];
/* WHOSE programme this is, so the coach's page can find their roster row —
   an explicit join rather than a match on the project's name (TASK-L165). */
Outputs.learnerId = programme.learnerId || '';
/* What a HISTORY query returns: the entries of their OTHER programmes, which
   the learner's own page never reads. In the product this is a separate,
   gated fetch the coach makes by choosing a programme (ProgrammeScope.tsx);
   here it is the second half of the same fixture (TASK-L165 §2). */
Outputs.history = programme.history || [];
/* WHAT THEY MUST PRODUCE (TASK-L166 §1). `deliverables` is the EFFECTIVE set
   as the product's getEffectiveDeliverables would return it for this learner —
   with ONE difference, and it is deliberate: the ARCHIVED row is still here. The
   product excludes it in the query; the template has no query, and a fixture
   that pre-filtered would make the rule untestable. Logic/Dossier decides who
   sees it, in one place. The coach-only fields (description, position,
   archivedAt, conceptIds) ride on the same rows. */
Outputs.deliverables = programme.deliverables || [];
/* The project context's flat facts, `<slug>.<factName>`, in the order they were
   captured — plus two un-namespaced ones the meter ignores and the coach still
   reads (one an onboarding fact with the pack's own label, one not). */
Outputs.facts = programme.facts || {};
/* Content-free, one row per ATTEMPT, as /api/course carries them. One is filed
   under an objective and one is not (L114: ambiguity resolves to null). The
   unfiled one has no timeline entry: it renders on no dossier surface by
   design, and adding it to `entries` would change /course (§1: the existing
   outputs do not change). */
Outputs.submissions = programme.submissions || [];
/* The pack's onboarding facts and their authored labels (a pack value). */
Outputs.onboardingFacts = programme.onboardingFacts || [];
/* Concept id -> the title the learner sees on their path: the product's
   `stepTitleByConceptId`, DERIVED from the lesson entries rather than authored
   beside them, so the two cannot drift. A concept that is not on the path has
   no title here and renders as its slug, as the product's `?? id` does. */
Outputs.concepts = (programme.entries || [])
  .filter((e) => e.kind === 'lesson' && e.conceptId)
  .map((e) => ({ id: e.conceptId, title: e.title }));
Outputs.loaded();

/*
 * WHICH PROGRAMME, AND WHEN TO ASK (TASK-L171 §1).
 *
 * The fixture fed three pages from ONE shape. The backend splits it by WHO IS
 * READING, and that split is the gate, not a detail:
 *
 *   learner -> `course`            their own programme; no parameter, so the
 *                                  learner is the session and nothing else
 *   coach   -> `learnerProgramme`  a named learner's; `role:staff` only
 *
 * Both answer with the fixture's own shape (L170), so fp_split is unchanged.
 *
 * NOT ARRIVED YET IS NOT THE SAME AS WIRED WRONG (Logic/Roster filter's rule):
 * an absent reader waits, and a reader that ARRIVES as anything else throws by
 * name. A coach's page waits for its learner id the same way.
 */
const reader = Inputs.reader;
if (reader === undefined || reader === null || reader === '') return;
if (reader !== 'learner' && reader !== 'coach') {
  throw new Error('Data/Programme: `reader` is "learner" or "coach", got ' + JSON.stringify(reader) + ' (TASK-L171).');
}
if (reader === 'learner') {
  Outputs.askOwn();
  return;
}
const id = String(Inputs.learnerId || '');
if (!id) return;
Outputs.learnerId = id;
Outputs.askAbout();
